package com.example.defyingtheheavens.client;

import com.example.defyingtheheavens.ModLang;
import net.fabricmc.fabric.api.datagen.v1.provider.FabricLanguageProvider;

/**
 * The heaven methods' English (HeavenMethod, and the five elements' spells they teach): their names, lore, what their layers
 * bring, and what each spell does. Generated from the design's sheets; kept apart from ModEnglishLangProvider for its length.
 */
final class HeavenLangText {
	static void add(FabricLanguageProvider.TranslationBuilder t) {
		// Green Sprout Breathing Manual
		t.add(ModLang.heavenMethodKey("green_sprout_breathing_manual"), "Green Sprout Breathing Manual");
		t.add(ModLang.heavenMethodKey("green_sprout_breathing_manual") + ".description", "Village hermits copied this primer from the margins of an old almanac. It teaches you to breathe the way a seed breathes when it splits its husk, drawing green qi up from the soil through the soles of the feet; humble and patient, it is the root every Wood art grows from.");
		t.add(ModLang.heavenMethodKey("green_sprout_breathing_manual") + ".gains", "Qi Refining, nine layers (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Wood Bullet (layer 2), Emerald Healing Art (layer 5), Verdant Growth (layer 8). Every layer: Evergreen Vitality.");
		// Coiling Vine Scripture
		t.add(ModLang.heavenMethodKey("coiling_vine_scripture"), "Coiling Vine Scripture");
		t.add(ModLang.heavenMethodKey("coiling_vine_scripture") + ".description", "A recluse left it in a ruined mountain shrine after watching wild vines pull the shrine's walls down over forty springs. It teaches qi to climb, to coil and never to let go.");
		t.add(ModLang.heavenMethodKey("coiling_vine_scripture") + ".gains", "Qi Refining to Foundation Building, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Life Force Drain (layer 11), Life Force Gain (layer 14), Mysterious Bristle Prison (layer 17). It teaches the wood spells of every realm below it too. Every layer: Evergreen Vitality.");
		// Ancient Cypress Art
		t.add(ModLang.heavenMethodKey("ancient_cypress_art"), "Ancient Cypress Art");
		t.add(ModLang.heavenMethodKey("ancient_cypress_art") + ".description", "Carved into the bark of a cypress that outlived three dynasties, this art teaches the cultivator to grow ring upon ring and endure every storm, and to scatter thorns among its roots for whatever comes to fell it.");
		t.add(ModLang.heavenMethodKey("ancient_cypress_art") + ".gains", "Qi Refining to Core Formation, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Thousand Leaf Storm (layer 21), Ancient Bark Skin (layer 25). It teaches the wood spells of every realm below it too. Every layer: Evergreen Vitality.");
		// Primeval Forest Canon
		t.add(ModLang.heavenMethodKey("primeval_forest_canon"), "Primeval Forest Canon");
		t.add(ModLang.heavenMethodKey("primeval_forest_canon") + ".description", "The canon of a forest sect whose elders sat beneath the trees so long that none could say where their meridians ended and the roots began. Its cultivator becomes a whole wood, drowsy with blossom and bristling with thorns.");
		t.add(ModLang.heavenMethodKey("primeval_forest_canon") + ".gains", "Qi Refining to Nascent Soul, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Thorn Spear Forest (layer 30), Lotus of Rebirth (layer 34). It teaches the wood spells of every realm below it too. Every layer: Evergreen Vitality.");
		// Eternal Spring Sutra
		t.add(ModLang.heavenMethodKey("eternal_spring_sutra"), "Eternal Spring Sutra");
		t.add(ModLang.heavenMethodKey("eternal_spring_sutra") + ".description", "Recited in the peach gardens of the immortals, where spring never yields to autumn. Here life renews itself without pause and mends the wounds of all it shelters, and what it cannot grow it takes, as the strangler fig takes its host.");
		t.add(ModLang.heavenMethodKey("eternal_spring_sutra") + ".gains", "Qi Refining to Heavenly Being, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Heaven-Piercing Bamboo (layer 39), Spring of Myriad Life (layer 43). It teaches the wood spells of every realm below it too. Every layer: Evergreen Vitality.");
		// Heaven-Bearing World Tree Classic
		t.add(ModLang.heavenMethodKey("heaven_bearing_world_tree_classic"), "Heaven-Bearing World Tree Classic");
		t.add(ModLang.heavenMethodKey("heaven_bearing_world_tree_classic") + ".description", "The root-script of the tree that stood where the four axes meet before heaven and earth were parted, bearing the sky upon its branches. Whoever completes it carries a world within their trunk, and all beneath its shade are kept.");
		t.add(ModLang.heavenMethodKey("heaven_bearing_world_tree_classic") + ".gains", "Qi Refining to Four Axis, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Myriad Vine Binding (layer 48), World Tree (layer 52). It teaches the wood spells of every realm below it too. Every layer: Evergreen Vitality.");
		// Morning Dew Gathering Art
		t.add(ModLang.heavenMethodKey("morning_dew_gathering_art"), "Morning Dew Gathering Art");
		t.add(ModLang.heavenMethodKey("morning_dew_gathering_art") + ".description", "A humble breathing art of river hermits. You sit among wet grass before sunrise and draw in the cold qi that settles with the dew, until your meridians run as clear as a mountain brook.");
		t.add(ModLang.heavenMethodKey("morning_dew_gathering_art") + ".gains", "Qi Refining, nine layers (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Water Arrow (layer 2), Azure Coating Technique (layer 5), Azure Breathing Technique (layer 8). Every layer: Ceaseless Flow.");
		// Clear Fount Cleansing Manual
		t.add(ModLang.heavenMethodKey("clear_fount_cleansing_manual"), "Clear Fount Cleansing Manual");
		t.add(ModLang.heavenMethodKey("clear_fount_cleansing_manual") + ".description", "Written beside a fount that never froze and never failed. It teaches qi to rise from deep in the body as spring water rises from the rock, washing every impurity away as it climbs.");
		t.add(ModLang.heavenMethodKey("clear_fount_cleansing_manual") + ".gains", "Qi Refining to Foundation Building, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Rain Call (layer 11), Water Prison (layer 14), Torrential Spring (layer 17). It teaches the water spells of every realm below it too. Every layer: Ceaseless Flow.");
		// Nine-Bend River Record
		t.add(ModLang.heavenMethodKey("nine_bend_river_record"), "Nine-Bend River Record");
		t.add(ModLang.heavenMethodKey("nine_bend_river_record") + ".description", "A record of the great river that turns nine times on its way to the sea, never contending with the mountains yet wearing them all away. From it the cultivator learns to bend, to coil and to carry.");
		t.add(ModLang.heavenMethodKey("nine_bend_river_record") + ".gains", "Qi Refining to Core Formation, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Tidal Lance (layer 21), Mist Veil (layer 25). It teaches the water spells of every realm below it too. Every layer: Ceaseless Flow.");
		// Moon-Mirror Lake Sutra
		t.add(ModLang.heavenMethodKey("moon_mirror_lake_sutra"), "Moon-Mirror Lake Sutra");
		t.add(ModLang.heavenMethodKey("moon_mirror_lake_sutra") + ".description", "Composed by a recluse who sat for a hundred years beside a lake so still that it held the moon twice. The sutra teaches the heart to become still water, reflecting all things and holding none.");
		t.add(ModLang.heavenMethodKey("moon_mirror_lake_sutra") + ".gains", "Qi Refining to Nascent Soul, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Glacial Spears (layer 30), Great Tide (layer 34). It teaches the water spells of every realm below it too. Every layer: Ceaseless Flow.");
		// Heavenly River Scripture
		t.add(ModLang.heavenMethodKey("heavenly_river_scripture"), "Heavenly River Scripture");
		t.add(ModLang.heavenMethodKey("heavenly_river_scripture") + ".description", "Said to be copied from the starry river that divides the sky. It teaches qi to fall from the heavens with the whole weight of the celestial current behind it, and to drown whatever it closes over.");
		t.add(ModLang.heavenMethodKey("heavenly_river_scripture") + ".gains", "Qi Refining to Heavenly Being, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Heavenly River Torrent (layer 39), Frozen Field (layer 43). It teaches the water spells of every realm below it too. Every layer: Ceaseless Flow.");
		// Boundless Four Seas Canon
		t.add(ModLang.heavenMethodKey("boundless_four_seas_canon"), "Boundless Four Seas Canon");
		t.add(ModLang.heavenMethodKey("boundless_four_seas_canon") + ".description", "The canon of the waters that ring the world at its four axes, from which every river comes and to which every river returns. At its end lies the abyss of the north, where even time stands frozen.");
		t.add(ModLang.heavenMethodKey("boundless_four_seas_canon") + ".gains", "Qi Refining to Four Axis, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Absolute Zero (layer 48), Boundless Sea (layer 52). It teaches the water spells of every realm below it too. Every layer: Ceaseless Flow.");
		// Ember Kindling Art
		t.add(ModLang.heavenMethodKey("ember_kindling_art"), "Ember Kindling Art");
		t.add(ModLang.heavenMethodKey("ember_kindling_art") + ".description", "A hearth-keeper's method handed down in mountain villages. Breath is banked in the dantian like coals under ash at night and fanned again at dawn, so that even the smallest ember of qi never goes out.");
		t.add(ModLang.heavenMethodKey("ember_kindling_art") + ".gains", "Qi Refining, nine layers (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Flame Bolt (layer 2), Flame Fist (layer 5), Crimson Tempering (layer 8). Every layer: Fury of the Fanned Flame.");
		// Furnace Heart Manual
		t.add(ModLang.heavenMethodKey("furnace_heart_manual"), "Furnace Heart Manual");
		t.add(ModLang.heavenMethodKey("furnace_heart_manual") + ".description", "The foundation is laid as the floor of a furnace beneath the heart. Breath works the bellows, each layer tempers the furnace walls, and whatever is thrown into its fire is refined, not lost.");
		t.add(ModLang.heavenMethodKey("furnace_heart_manual") + ".gains", "Qi Refining to Foundation Building, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Remote Yang Bomb (layer 11), Flame Armour (layer 14), Fire Serpent (layer 17). It teaches the fire spells of every realm below it too. Every layer: Fury of the Fanned Flame.");
		// Crimson Crucible Classic
		t.add(ModLang.heavenMethodKey("crimson_crucible_classic"), "Crimson Crucible Classic");
		t.add(ModLang.heavenMethodKey("crimson_crucible_classic") + ".description", "Written by an alchemist who held that a golden core is only ore until it is smelted. The body becomes a crucible, and the core is poured from fire refined nine times over, until it blooms like a lotus in the flame.");
		t.add(ModLang.heavenMethodKey("crimson_crucible_classic") + ".gains", "Qi Refining to Core Formation, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Crimson Swirl (layer 21), Solar Field (layer 25). It teaches the fire spells of every realm below it too. Every layer: Fury of the Fanned Flame.");
		// Vermilion Bird Sutra
		t.add(ModLang.heavenMethodKey("vermilion_bird_sutra"), "Vermilion Bird Sutra");
		t.add(ModLang.heavenMethodKey("vermilion_bird_sutra") + ".description", "The Nascent Soul is hatched in the fire of the south and takes the shape of the Vermilion Bird, guardian of the summer quarter of the sky. Its talons sear what they touch, and its descent sets the plains alight.");
		t.add(ModLang.heavenMethodKey("vermilion_bird_sutra") + ".gains", "Qi Refining to Nascent Soul, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Karmic Fire (layer 30), Blazing Meteor (layer 34). It teaches the fire spells of every realm below it too. Every layer: Fury of the Fanned Flame.");
		// Golden Crow Great Sun Scripture
		t.add(ModLang.heavenMethodKey("golden_crow_great_sun_scripture"), "Golden Crow Great Sun Scripture");
		t.add(ModLang.heavenMethodKey("golden_crow_great_sun_scripture") + ".description", "Said to be copied from the marks the three-legged golden crow left on the great mulberry of the eastern sea before it carried the sun across the sky. Its practitioners learn to bear a sun within them, as bright as noon.");
		t.add(ModLang.heavenMethodKey("golden_crow_great_sun_scripture") + ".gains", "Qi Refining to Heavenly Being, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Phoenix Descent (layer 39), Sea of Flames (layer 43). It teaches the fire spells of every realm below it too. Every layer: Fury of the Fanned Flame.");
		// Heaven-Burning Phoenix Nirvana Canon
		t.add(ModLang.heavenMethodKey("heaven_burning_phoenix_nirvana_canon"), "Heaven-Burning Phoenix Nirvana Canon");
		t.add(ModLang.heavenMethodKey("heaven_burning_phoenix_nirvana_canon") + ".description", "The highest fire under the four axes of heaven, the fire of the phoenix that burns itself to ash and rises again. Its masters set storms of flame loose across the sky and, once in a long while, refuse death itself.");
		t.add(ModLang.heavenMethodKey("heaven_burning_phoenix_nirvana_canon") + ".gains", "Qi Refining to Four Axis, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Nine Suns Descend (layer 48), Phoenix Nirvana (layer 52). It teaches the fire spells of every realm below it too. Every layer: Fury of the Fanned Flame.");
		// Rammed Earth Manual
		t.add(ModLang.heavenMethodKey("rammed_earth_manual"), "Rammed Earth Manual");
		t.add(ModLang.heavenMethodKey("rammed_earth_manual") + ".description", "A village builder's manual, its pages stiff with dried clay. It teaches the body to take in the soil's qi one layer at a time, packed hard, the way earth is rammed between boards to raise a wall.");
		t.add(ModLang.heavenMethodKey("rammed_earth_manual") + ".gains", "Qi Refining, nine layers (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Earth Spear (layer 2), Hardened Body (layer 5), Dirt Tide (layer 8). Every layer: Unshaken Mountain Body.");
		// Thousand-Layer Stone Record
		t.add(ModLang.heavenMethodKey("thousand_layer_stone_record"), "Thousand-Layer Stone Record");
		t.add(ModLang.heavenMethodKey("thousand_layer_stone_record") + ".description", "Copied from a cliff face by a hermit who read the strata like the pages of a book. It records stone laid on stone over ten thousand years, each layer pressing the one beneath into something harder.");
		t.add(ModLang.heavenMethodKey("thousand_layer_stone_record") + ".gains", "Qi Refining to Foundation Building, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Earth Wall Technique (layer 11), Boulder Throw (layer 14), Cave Formation (layer 17). It teaches the earth spells of every realm below it too. Every layer: Unshaken Mountain Body.");
		// Five Sacred Peaks Classic
		t.add(ModLang.heavenMethodKey("five_sacred_peaks_classic"), "Five Sacred Peaks Classic");
		t.add(ModLang.heavenMethodKey("five_sacred_peaks_classic") + ".description", "The five sacred mountains stand at the four quarters and the centre of the land. This classic teaches the cultivator to gather their weight into a single core that nothing under heaven can shift.");
		t.add(ModLang.heavenMethodKey("five_sacred_peaks_classic") + ".gains", "Qi Refining to Core Formation, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Earth Dragon Surge (layer 21), Mountain Stance (layer 25). It teaches the earth spells of every realm below it too. Every layer: Unshaken Mountain Body.");
		// Yellow Dragon Earth-Vein Canon
		t.add(ModLang.heavenMethodKey("yellow_dragon_earth_vein_canon"), "Yellow Dragon Earth-Vein Canon");
		t.add(ModLang.heavenMethodKey("yellow_dragon_earth_vein_canon") + ".description", "Beneath every mountain run the earth's veins, and in them sleeps the Yellow Dragon of the Centre. This canon teaches the nascent soul to swim those veins beside it, and to wake it.");
		t.add(ModLang.heavenMethodKey("yellow_dragon_earth_vein_canon") + ".gains", "Qi Refining to Nascent Soul, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Summon Golem (layer 30), Earthquake (layer 34). It teaches the earth spells of every realm below it too. Every layer: Unshaken Mountain Body.");
		// Sovereign Earth Myriad-Bearing Sutra
		t.add(ModLang.heavenMethodKey("sovereign_earth_myriad_bearing_sutra"), "Sovereign Earth Myriad-Bearing Sutra");
		t.add(ModLang.heavenMethodKey("sovereign_earth_myriad_bearing_sutra") + ".description", "Sovereign Earth carries every mountain, river and living thing and never once complains of the weight. Those who recite this sutra learn to bear what others cannot, and to become the ground beneath their companions' feet.");
		t.add(ModLang.heavenMethodKey("sovereign_earth_myriad_bearing_sutra") + ".gains", "Qi Refining to Heavenly Being, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Falling Mountain (layer 39), Heavy Earth Seal (layer 43). It teaches the earth spells of every realm below it too. Every layer: Unshaken Mountain Body.");
		// Four Pillars Upholding Heaven Scripture
		t.add(ModLang.heavenMethodKey("four_pillars_upholding_heaven_scripture"), "Four Pillars Upholding Heaven Scripture");
		t.add(ModLang.heavenMethodKey("four_pillars_upholding_heaven_scripture") + ".description", "When Mount Buzhou broke and the sky tilted, four pillars were raised at the ends of the world to hold heaven up again. This scripture is found only above the clouds, and is said to be cut into the stone of those pillars themselves.");
		t.add(ModLang.heavenMethodKey("four_pillars_upholding_heaven_scripture") + ".gains", "Qi Refining to Four Axis, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Earthen Titan (layer 48), Mountain Seal (layer 52). It teaches the earth spells of every realm below it too. Every layer: Unshaken Mountain Body.");
		// Whetstone Edge Manual
		t.add(ModLang.heavenMethodKey("whetstone_edge_manual"), "Whetstone Edge Manual");
		t.add(ModLang.heavenMethodKey("whetstone_edge_manual") + ".description", "A smith's apprentice's manual, its pages black with forge soot: grind your qi as a whetstone grinds iron and hang it about the body like an iron bell, until one thread of it grows keen enough to fly out and come home.");
		t.add(ModLang.heavenMethodKey("whetstone_edge_manual") + ".gains", "Qi Refining, nine layers (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Flying Sword (layer 2), Blade Polish (layer 5), Steel Hurricane (layer 8). Every layer: Whetted Edge.");
		// Hundred-Forged Lodestone Art
		t.add(ModLang.heavenMethodKey("hundred_forged_lodestone_art"), "Hundred-Forged Lodestone Art");
		t.add(ModLang.heavenMethodKey("hundred_forged_lodestone_art") + ".description", "The foundation is folded a hundred times like sword steel and laid about a lodestone heart. Iron leans toward its practitioner, and the weapons of others grow heavy in their hands.");
		t.add(ModLang.heavenMethodKey("hundred_forged_lodestone_art") + ".gains", "Qi Refining to Foundation Building, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Boulder Cleave (layer 11), Mineral Purification (layer 14), Advanced Flying Sword Technique (layer 17). It teaches the metal spells of every realm below it too. Every layer: Whetted Edge.");
		// Golden Thunder Core Sutra
		t.add(ModLang.heavenMethodKey("golden_thunder_core_sutra"), "Golden Thunder Core Sutra");
		t.add(ModLang.heavenMethodKey("golden_thunder_core_sutra") + ".description", "Left in a cave beneath the Thunder Peaks by a sword cultivator who let heaven's lightning hammer his core like an anvil until it rang gold. Its practitioners point and armour splits; they open their hand and the thunder leaps.");
		t.add(ModLang.heavenMethodKey("golden_thunder_core_sutra") + ".gains", "Qi Refining to Core Formation, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Sword Rain (layer 21), Golden Bell Shield (layer 25). It teaches the metal spells of every realm below it too. Every layer: Whetted Edge.");
		// Nine Bells Sword-Soul Classic
		t.add(ModLang.heavenMethodKey("nine_bells_sword_soul_classic"), "Nine Bells Sword-Soul Classic");
		t.add(ModLang.heavenMethodKey("nine_bells_sword_soul_classic") + ".description", "The nascent soul is cast like a great bell with nine swords hung inside it. When it tolls, every blade answers, and all who hear it share one another's wounds.");
		t.add(ModLang.heavenMethodKey("nine_bells_sword_soul_classic") + ".gains", "Qi Refining to Nascent Soul, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Piercing Sword Light (layer 30), Vajra Body (layer 34). It teaches the metal spells of every realm below it too. Every layer: Whetted Edge.");
		// Heaven-Severing Sword Scripture
		t.add(ModLang.heavenMethodKey("heaven_severing_sword_scripture"), "Heaven-Severing Sword Scripture");
		t.add(ModLang.heavenMethodKey("heaven_severing_sword_scripture") + ".description", "Recovered from the deepest grave of the Ancient Sword Graveyard, a scripture of the edge that cuts even karma, severing whatever heaven has granted. At its height the practitioner calls down the swords of every master buried there.");
		t.add(ModLang.heavenMethodKey("heaven_severing_sword_scripture") + ".gains", "Qi Refining to Heavenly Being, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Mountain Cleave (layer 39), Sword Domain (layer 43). It teaches the metal spells of every realm below it too. Every layer: Whetted Edge.");
		// Four Swords Immortal-Slaying Canon
		t.add(ModLang.heavenMethodKey("four_swords_immortal_slaying_canon"), "Four Swords Immortal-Slaying Canon");
		t.add(ModLang.heavenMethodKey("four_swords_immortal_slaying_canon") + ".description", "The Metal at the four axes of the world, forged into four swords that stand at the gates of creation. Whoever enters their array is never let out, and whoever wears this Canon's golden body is broken by no single blow.");
		t.add(ModLang.heavenMethodKey("four_swords_immortal_slaying_canon") + ".gains", "Qi Refining to Four Axis, nine layers a realm (of each realm's nine, layer 1 Early, 3 Mid, 6 Late, 9 Grand Perfection; each opens when your cultivation reaches it). Its realm's spells: Heaven-Severing Sword (layer 48), Four Swords Array (layer 52). It teaches the metal spells of every realm below it too. Every layer: Whetted Edge.");
		// The five elements' spells
		t.add(ModLang.spellKey("flame_bolt"), "Flame Bolt");
		t.add(ModLang.spellKey("flame_bolt") + ".description", "Shoots a bolt of red flame from your hand at where you aim, up to 40 blocks. It strikes for 5 fire harm and sets its mark burning for 3 s. Water puts it out: a being under a water ward (Azure Coating) takes none of it.");
		t.add(ModLang.spellKey("flame_fist"), "Flame Fist");
		t.add(ModLang.spellKey("flame_fist") + ".description", "For 15 s your fists burn with red and orange flame. Every blow you land sets its mark burning for 5 s and sears it for 1 more fire harm. Against a being under a water ward the flames only hiss out.");
		t.add(ModLang.spellKey("crimson_tempering"), "Crimson Tempering");
		t.add(ModLang.spellKey("crimson_tempering") + ".description", "For 30 s fire and lava cannot burn you, and lava bears your weight: you can walk and run across it. A fire ward.");
		t.add(ModLang.spellKey("wood_bullet"), "Wood Bullet");
		t.add(ModLang.spellKey("wood_bullet") + ".description", "Grows a sharp wooden stake in the air before you, then shoots it at where you aim, up to 40 blocks: 5 wood harm and a small knock back. Against a fire ward (Crimson Tempering, Flame Armour) the stake burns to ash.");
		t.add(ModLang.spellKey("emerald_healing_art"), "Emerald Healing Art");
		t.add(ModLang.spellKey("emerald_healing_art") + ".description", "For 10 s you heal 1 health every second, fed or hungry, and glow a faint green.");
		t.add(ModLang.spellKey("verdant_growth"), "Verdant Growth");
		t.add(ModLang.spellKey("verdant_growth") + ".description", "A tree grows up out of the ground under your feet in two seconds, lifting you 14 blocks into the air on its trunk, and spreads a blossoming crown round you at the top. It stands for 60 s, then withers away; its wood and leaves give nothing when broken. Cast it standing on the ground.");
		t.add(ModLang.spellKey("earth_spear"), "Earth Spear");
		t.add(ModLang.spellKey("earth_spear") + ".description", "Raises clods of earth into the air before you, where they fuse into a podao of dried earth, then flings it at where you aim, up to 40 blocks: 6 earth harm and a heavy knock back.");
		t.add(ModLang.spellKey("hardened_body"), "Hardened Body");
		t.add(ModLang.spellKey("hardened_body") + ".description", "For 30 s a thin skin of stone covers you, taking 7% off all harm you take (14% off water's). An earth ward.");
		t.add(ModLang.spellKey("dirt_tide"), "Dirt Tide");
		t.add(ModLang.spellKey("dirt_tide") + ".description", "Raises a wave of the earth you stand on and carries you on its crest for 10 s, the way you face, faster than a sprint: forward drives it on, back reins it in, and it climbs a block at a time and rides over water. Sneak to step off.");
		t.add(ModLang.spellKey("water_arrow"), "Water Arrow");
		t.add(ModLang.spellKey("water_arrow") + ".description", "Forms an arrow of swirling water in the air and shoots it at where you aim, up to 40 blocks: 5 water harm, and whatever burns on its mark is put out. Strong against fire wards.");
		t.add(ModLang.spellKey("azure_coating_technique"), "Azure Coating Technique");
		t.add(ModLang.spellKey("azure_coating_technique") + ".description", "For 30 s a thin coat of water clings to you: fire cannot burn you and fire spells stop at it (a fire spell of a deeper realm than this still breaks half through). Lava boils it away. A water ward.");
		t.add(ModLang.spellKey("azure_breathing_technique"), "Azure Breathing Technique");
		t.add(ModLang.spellKey("azure_breathing_technique") + ".description", "For 60 s you can walk and run on water (sneak to sink into it) and breathe under it.");
		t.add(ModLang.spellKey("flying_sword"), "Flying Sword");
		t.add(ModLang.spellKey("flying_sword") + ".description", "Forms a sword of metal in the air before you, shard by shard, and shoots it at where you aim, up to 48 blocks: 6 metal harm, and it flies on through its first mark to strike another.");
		t.add(ModLang.spellKey("blade_polish"), "Blade Polish");
		t.add(ModLang.spellKey("blade_polish") + ".description", "For 30 s every melee blow you strike deals 1.2 times its harm, and the weapon in your hand gives off a faint white glow and wisps of white smoke.");
		t.add(ModLang.spellKey("steel_hurricane"), "Steel Hurricane");
		t.add(ModLang.spellKey("steel_hurricane") + ".description", "You dash the way you look with your weapon thrust before you, spinning like a trident's riptide, for 1.6 s: every being you meet takes your weapon's blow and 3 metal harm more. No fall harm from it.");
		t.add(ModLang.spellKey("remote_yang_bomb"), "Remote Yang Bomb");
		t.add(ModLang.spellKey("remote_yang_bomb") + ".description", "Leaves a ball of yang fire on the surface you look at, within 16 blocks. Only you, and those with Qi Sense open, can see it. While it waits it draws 1 qi a second from you. Cast the spell again within 48 blocks to set it off: 14 fire harm to everything within 4 blocks, burning for 4 s, and a blast that throws them back. Setting it off costs nothing; the spell then rests for 15 s. It gutters out if your qi runs dry or you go far from it.");
		t.add(ModLang.spellKey("flame_armour"), "Flame Armour");
		t.add(ModLang.spellKey("flame_armour") + ".description", "For 30 s you are clad in armour made of red flame, from its burning crest to its greaves. It takes 10% off all harm you take, and 20% off metal's (metal spells, and blows of iron, gold, diamond or netherite weapons). A fire ward.");
		t.add(ModLang.spellKey("fire_serpent"), "Fire Serpent");
		t.add(ModLang.spellKey("fire_serpent") + ".description", "A serpent of fire coils out of your hand and swims through the air at where you aim, bending toward its mark as it goes, up to 48 blocks: 12 fire harm and burning for 4 s.");
		t.add(ModLang.spellKey("life_force_drain"), "Life Force Drain");
		t.add(ModLang.spellKey("life_force_drain") + ".description", "For 6 s you draw the life out of the being you look at or a herb growing there (a ginseng), within 12 blocks, or the years out of a single Cultivation Fruit or herb you hold (a fruit on its tree can't be drawn on). A being loses 1.5 health a second, and it heals you; a herb or fruit loses 60 years a second, and you heal 1 a second. A stream of emerald light runs from it to you. It breaks if you stray 16 blocks apart. Herbs in a sect's or a Ghost King's treasury can't be touched while its seal holds.");
		t.add(ModLang.spellKey("life_force_gain"), "Life Force Gain");
		t.add(ModLang.spellKey("life_force_gain") + ".description", "For 6 s you pour your own life into the being you look at, or into an aging herb or fruit growing within 12 blocks, or a single one you hold: you lose 1 health a second (never below 4), and a being heals 2 a second, or a herb gains 120 years a second. Herbs in a sealed treasury can't be touched.");
		t.add(ModLang.spellKey("mysterious_bristle_prison"), "Mysterious Bristle Prison");
		t.add(ModLang.spellKey("mysterious_bristle_prison") + ".description", "Thorny bristles burst up out of the ground round the being you look at, within 20 blocks, and close over it: it is held where it stands for 4 s, torn for 1.5 wood harm a second. Three blows on the cage break it, from outside or in; but each one the prisoner strikes from inside tears it for 2 more.");
		t.add(ModLang.spellKey("earth_wall_technique"), "Earth Wall Technique");
		t.add(ModLang.spellKey("earth_wall_technique") + ".description", "A wall of the ground you stand on, 6 blocks long and 4 tall, rises out of the earth 3 blocks ahead of you, across your way. If you are not on the ground, it forms in mid air, from its middle block outward. It stands for 30 s, then sinks back into the ground.");
		t.add(ModLang.spellKey("boulder_throw"), "Boulder Throw");
		t.add(ModLang.spellKey("boulder_throw") + ".description", "Tears a boulder out of the ground ahead of you, leaving a round hole two blocks deep, gathers it in the air and throws it at where you aim, up to 48 blocks: 16 earth harm and a heavy knock back. It tears it from whatever lies ahead, ground or what is built there (not inside a barrier).");
		t.add(ModLang.spellKey("cave_formation"), "Cave Formation");
		t.add(ModLang.spellKey("cave_formation") + ".description", "Carves a cave fit for one into the slope or ground you look at, within 6 blocks, crumbling it away before your eyes over 3 s: into a slope, an entrance one block wide and two tall with a room three blocks wide, deep and tall behind it; into the ground, three steps down to such a room.");
		t.add(ModLang.spellKey("rain_call"), "Rain Call");
		t.add(ModLang.spellKey("rain_call") + ".description", "Calls a rain cloud of your own over where you stand, 8 blocks round, for 20 s. Everyone under it but you is slowed by a tenth, and the rain puts out fires and whatever burns.");
		t.add(ModLang.spellKey("water_prison"), "Water Prison");
		t.add(ModLang.spellKey("water_prison") + ".description", "Encases the being you look at, within 16 blocks, in a sphere of water for 5 s. The air is drawn out of it at once: it drowns from the first second (no held breath), takes 2 water harm a second besides, and is held where it is. 30 harm struck on the sphere bursts it, the prisoner's own blows from inside too.");
		t.add(ModLang.spellKey("torrential_spring"), "Torrential Spring");
		t.add(ModLang.spellKey("torrential_spring") + ".description", "Gathers a great ball of water out of the air above and ahead of you over 1.5 s, then drops it on where you look, up to 32 blocks: 8 water harm to everything within 4 blocks, a heavy wash that throws them back, and a small lake pressed into the ground where it falls.");
		t.add(ModLang.spellKey("boulder_cleave"), "Boulder Cleave");
		t.add(ModLang.spellKey("boulder_cleave") + ".description", "Flings a crescent of sword qi from you the way you look. It flies 15 blocks through the ground as through air, cutting a slot 3 blocks wide and 2 tall through everything it passes (what it cuts is gone), and cleaves every being in its way for 14 metal harm.");
		t.add(ModLang.spellKey("mineral_purification"), "Mineral Purification");
		t.add(ModLang.spellKey("mineral_purification") + ".description", "Every ore within the reach of your consciousness (your Consciousness Domain's radius) gives up its ore: it streams to you as light and is yours, as mined and unsmelted, the rock it lay in left behind. At most 256 ores, the nearest first. Ores inside a raised barrier (protective or concealment) are beyond its reach.");
		t.add(ModLang.spellKey("advanced_flying_sword_technique"), "Advanced Flying Sword Technique");
		t.add(ModLang.spellKey("advanced_flying_sword_technique") + ".description", "Six swords form in the air round you one after another, then fly one after another at where you look: 9 metal harm each, each passing through one being to strike another.");
		t.add(ModLang.spellKey("crimson_swirl"), "Crimson Swirl");
		t.add(ModLang.spellKey("crimson_swirl") + ".description", "A great tornado of fire rises 3 blocks ahead of you and creeps toward where you aim (up to 40 blocks away) for 10 s. It drags in and lifts whatever comes near, burns all within it for 6 fire harm a second, tears up the ground beneath it (and what is built there) and leaves fire behind.");
		t.add(ModLang.spellKey("solar_field"), "Solar Field");
		t.add(ModLang.spellKey("solar_field") + ".description", "A small sun burns 8 blocks above you for 10 s. Everyone else within 40 blocks of you is set burning, every second, as if standing in fire (a water ward or a fire-proof body excepted).");
		t.add(ModLang.spellKey("thousand_leaf_storm"), "Thousand Leaf Storm");
		t.add(ModLang.spellKey("thousand_leaf_storm") + ".description", "Sixteen razor leaves stream from your palm over a second, each bending a little toward a foe: 2.5 wood harm each, every one its own cut. Against a fire ward they burn to ash.");
		t.add(ModLang.spellKey("ancient_bark_skin"), "Ancient Bark Skin");
		t.add(ModLang.spellKey("ancient_bark_skin") + ".description", "For 20 s ancient bark grows over you: 20% less harm taken, 40% less of earth's. A wood ward.");
		t.add(ModLang.spellKey("earth_dragon_surge"), "Earth Dragon Surge");
		t.add(ModLang.spellKey("earth_dragon_surge") + ".description", "A ridge of jagged spikes of the ground's own rock bursts up along the ground from you toward where you face, 24 blocks out, running out as fast as a horse: whatever it passes over takes 20 earth harm and is thrown into the air. The spikes sink back a few seconds later.");
		t.add(ModLang.spellKey("mountain_stance"), "Mountain Stance");
		t.add(ModLang.spellKey("mountain_stance") + ".description", "For 15 s you stand like a mountain, clad in slabs of stone: 25% less harm taken (50% less of water's), and nothing can knock you back, but you walk a fifth slower. An earth ward.");
		t.add(ModLang.spellKey("tidal_lance"), "Tidal Lance");
		t.add(ModLang.spellKey("tidal_lance") + ".description", "A jet of water bursts from your hands for 2 s, as far as 24 blocks: the first being in it takes 6 water harm every half second and is driven back along it.");
		t.add(ModLang.spellKey("mist_veil"), "Mist Veil");
		t.add(ModLang.spellKey("mist_veil") + ".description", "A thick mist rises 10 blocks round you for 15 s, moving with you: foes in it lose sight of you and your allies (unless within 3 blocks of them), and missiles flying into it slow to half their speed.");
		t.add(ModLang.spellKey("sword_rain"), "Sword Rain");
		t.add(ModLang.spellKey("sword_rain") + ".description", "Twelve swords form in a ring high over where you look, up to 32 blocks, and plunge down round it: 6 metal harm each.");
		t.add(ModLang.spellKey("golden_bell_shield"), "Golden Bell Shield");
		t.add(ModLang.spellKey("golden_bell_shield") + ".description", "A great golden bell comes down over you for 10 s and takes up to 40 harm for you, tolling with each blow; wood's harm costs it half as much, fire's twice. A metal ward.");
		t.add(ModLang.spellKey("karmic_fire"), "Karmic Fire");
		t.add(ModLang.spellKey("karmic_fire") + ".description", "Sets karmic fire on the being you look at, within 32 blocks, for 8 s, burning away its sins: each second it takes 1 harm if it is guiltless, up to 11 for a devil (by its alignment), 6 for a monster, a little for a beast or a villager. A sinner's alignment burns 2 a second toward neutral.");
		t.add(ModLang.spellKey("blazing_meteor"), "Blazing Meteor");
		t.add(ModLang.spellKey("blazing_meteor") + ".description", "Calls a burning meteor down out of the sky onto where you look, up to 48 blocks, its mark glowing on the ground as it falls: 45 fire harm to everything within 6 blocks, burning for 6 s, a scorched crater and fires round it.");
		t.add(ModLang.spellKey("thorn_spear_forest"), "Thorn Spear Forest");
		t.add(ModLang.spellKey("thorn_spear_forest") + ".description", "Spears of thorny wood burst out of the ground 6 blocks round where you look, up to 32 blocks: every foe there takes 35 wood harm and is held where it stands for 2 s.");
		t.add(ModLang.spellKey("lotus_of_rebirth"), "Lotus of Rebirth");
		t.add(ModLang.spellKey("lotus_of_rebirth") + ".description", "A great lotus opens at your feet for 10 s: you and every friendly being within 10 blocks are cleansed of harmful effects and fire at once, and heal 4 health a second while it blooms.");
		t.add(ModLang.spellKey("summon_golem"), "Summon Golem");
		t.add(ModLang.spellKey("summon_golem") + ".description", "Raises an earth golem out of the ground beside you for 90 s. It flies (at three fifths of a cultivator's flight), keeps by you and fights for you: whatever strikes you or you strike, or a monster that comes for you. 80 health, 18 earth harm a blow. Two at most: a third sends the oldest back to the earth.");
		t.add(ModLang.spellKey("earthquake"), "Earthquake");
		t.add(ModLang.spellKey("earthquake") + ".description", "The ground shakes 16 blocks round you for 4 s: every foe on the ground takes 10 earth harm a second, is slowed hard and thrown about.");
		t.add(ModLang.spellKey("glacial_spears"), "Glacial Spears");
		t.add(ModLang.spellKey("glacial_spears") + ".description", "Five spears of ice form over your head and fly in a fan at where you look: 14 water harm each, slowness for 3 s and the cold's frost.");
		t.add(ModLang.spellKey("great_tide"), "Great Tide");
		t.add(ModLang.spellKey("great_tide") + ".description", "A wave 10 blocks tall and 14 wide rolls out 30 blocks the way you face: whatever it overtakes takes 30 water harm, is swept along hard and put out.");
		t.add(ModLang.spellKey("piercing_sword_light"), "Piercing Sword Light");
		t.add(ModLang.spellKey("piercing_sword_light") + ".description", "A beam of sword light pierces everything along your look for 48 blocks (until a wall): 45 metal harm to each being in it.");
		t.add(ModLang.spellKey("vajra_body"), "Vajra Body");
		t.add(ModLang.spellKey("vajra_body") + ".description", "For 12 s your skin turns to gold: 35% less harm taken (70% less of wood's), nothing can knock you back, and whoever strikes you in melee takes 4 metal harm. A metal ward.");
		t.add(ModLang.spellKey("phoenix_descent"), "Phoenix Descent");
		t.add(ModLang.spellKey("phoenix_descent") + ".description", "A phoenix of fire takes wing from you and flies at where you aim, bending toward its mark, up to 64 blocks, and bursts there: 90 fire harm to everything within 5 blocks, burning for 6 s.");
		t.add(ModLang.spellKey("sea_of_flames"), "Sea of Flames");
		t.add(ModLang.spellKey("sea_of_flames") + ".description", "The ground 20 blocks round where you look, up to 48 blocks, becomes a sea of flame for 10 s: every foe standing in it takes 20 fire harm a second.");
		t.add(ModLang.spellKey("heaven_piercing_bamboo"), "Heaven-Piercing Bamboo");
		t.add(ModLang.spellKey("heaven_piercing_bamboo") + ".description", "Giant bamboo bursts up out of the ground under as many as 8 foes within 24 blocks of where you look: 80 wood harm each, and they are thrown high into the air.");
		t.add(ModLang.spellKey("spring_of_myriad_life"), "Spring of Myriad Life");
		t.add(ModLang.spellKey("spring_of_myriad_life") + ".description", "A green rain of life falls 32 blocks round you for 10 s: you and every friendly being in it heal 50 health at once, then 6 a second.");
		t.add(ModLang.spellKey("falling_mountain"), "Falling Mountain");
		t.add(ModLang.spellKey("falling_mountain") + ".description", "A mountain of rock forms in the sky over where you look, up to 64 blocks, and falls on it: 120 earth harm to everything within 8 blocks, a shockwave, and a crater 4 blocks round.");
		t.add(ModLang.spellKey("heavy_earth_seal"), "Heavy Earth Seal");
		t.add(ModLang.spellKey("heavy_earth_seal") + ".description", "Every foe within 24 blocks of you is pressed to the ground for 6 s: it cannot jump or fly (a flier is brought down), is slowed hard, and takes 15 earth harm a second.");
		t.add(ModLang.spellKey("heavenly_river_torrent"), "Heavenly River Torrent");
		t.add(ModLang.spellKey("heavenly_river_torrent") + ".description", "A river pours out of the sky along a line from you to where you look, 32 blocks, for 2 s: everyone in its fall takes 70 water harm and is swept along it.");
		t.add(ModLang.spellKey("frozen_field"), "Frozen Field");
		t.add(ModLang.spellKey("frozen_field") + ".description", "The cold runs out from you to 100 blocks round over three seconds: open water freezes, frost lies on the ground near you, and every being it reaches (but your allies and pets) is frozen solid for 4 s. The ice thaws over the next 20 to 40 s, and until it has, every being in the field takes 4 water harm a second.");
		t.add(ModLang.spellKey("mountain_cleave"), "Mountain Cleave");
		t.add(ModLang.spellKey("mountain_cleave") + ".description", "Flings a crescent of sword qi as tall as a tower the way you look. It flies 100 blocks, cutting a slot 3 blocks wide and 12 tall through hills and mountains alike (what it cuts is gone), and cleaves every being in its way for 150 metal harm.");
		t.add(ModLang.spellKey("sword_domain"), "Sword Domain");
		t.add(ModLang.spellKey("sword_domain") + ".description", "Thirty-six swords circle you 10 blocks round for 12 s: every foe within takes 20 metal harm every half second.");
		t.add(ModLang.spellKey("nine_suns_descend"), "Nine Suns Descend");
		t.add(ModLang.spellKey("nine_suns_descend") + ".description", "Nine suns fall out of the sky, one after another, onto where you look and round it, up to 64 blocks: each bursts for 150 fire harm 6 blocks round, burning for 6 s.");
		t.add(ModLang.spellKey("phoenix_nirvana"), "Phoenix Nirvana");
		t.add(ModLang.spellKey("phoenix_nirvana") + ".description", "For 60 s the phoenix's fire waits in you: if you would die, you rise again instead at full health, harmful effects burnt away, in a burst of flame that strikes everyone but your allies within 10 blocks for 200 fire harm. Once.");
		t.add(ModLang.spellKey("myriad_vine_binding"), "Myriad Vine Binding");
		t.add(ModLang.spellKey("myriad_vine_binding") + ".description", "Vines burst up and seize as many as 12 foes within 40 blocks of where you look, up to 64 blocks: each is held fast for 6 s and takes 30 wood harm a second.");
		t.add(ModLang.spellKey("world_tree"), "World Tree");
		t.add(ModLang.spellKey("world_tree") + ".description", "The World Tree grows out of the ground where you look (or before you) and towers over all for 15 s. Its vines reach from its boughs for every being but you within 32 blocks of its trunk (your pets spared), lift them into its branches and hold them there, drinking 15 of their health a second into you.");
		t.add(ModLang.spellKey("earthen_titan"), "Earthen Titan");
		t.add(ModLang.spellKey("earthen_titan") + ".description", "Raises an earth titan three times a golem's size beside you for 60 s: it flies, keeps by you and fights for you, 400 health and 80 earth harm a blow, its fist striking the ground round its mark too. One at a time.");
		t.add(ModLang.spellKey("mountain_seal"), "Mountain Seal");
		t.add(ModLang.spellKey("mountain_seal") + ".description", "A mountain of stone bursts up over where you look, up to 48 blocks, 6 blocks round and 8 tall: everything inside is entombed, held fast for 5 s and crushed for 60 earth harm a second. The mountain crumbles away after 20 s; its stone gives nothing.");
		t.add(ModLang.spellKey("absolute_zero"), "Absolute Zero");
		t.add(ModLang.spellKey("absolute_zero") + ".description", "A beam of utter cold freezes the being you look at solid, within 48 blocks: 200 water harm, and it is held frozen for 8 s. When anything strikes it, or the cold lets go, it shatters for 100 more.");
		t.add(ModLang.spellKey("boundless_sea"), "Boundless Sea");
		t.add(ModLang.spellKey("boundless_sea") + ".description", "A sphere of the sea 16 blocks round fills the place you look at, up to 48 blocks, for 10 s: every foe inside is held in it, drowning, and takes 30 water harm a second.");
		t.add(ModLang.spellKey("heaven_severing_sword"), "Heaven-Severing Sword");
		t.add(ModLang.spellKey("heaven_severing_sword") + ".description", "A sword as tall as a tower falls out of the sky onto where you look, up to 64 blocks: 300 metal harm to everything within 4 blocks, and a trench 20 blocks long, 3 wide and 10 deep cut into the earth along your facing.");
		t.add(ModLang.spellKey("four_swords_array"), "Four Swords Array");
		t.add(ModLang.spellKey("four_swords_array") + ".description", "Four giant swords plant themselves at the corners of a square 32 blocks across round where you look, up to 48 blocks: for 8 s every foe inside is held in by the walls of light between them and takes 80 metal harm a second.");
	}

	private HeavenLangText() {}
}
